Cho tam giác đều cạnh bằng ${9}cm$. Bán kính đường tròn ngoại tiếp tam giác đó là bao nhiêu? 

\choice
{  ${3 \sqrt{6}}$ }
   { ${\dfrac{9 \sqrt{3}}{2}}$  }
     { ${\dfrac{3 \sqrt{3}}{2}}$  }
    { \True  ${3 \sqrt{3}}$ }
}{
\begin{tikzpicture}
    % Vẽ đường tròn tâm O bán kính 3
    \draw[thick] (0,0) circle (3);

    % Định nghĩa điểm O
    \coordinate [label=below right:$O$] (O) at (0,0);

    % Định nghĩa các đỉnh của tam giác đều ABC
    \coordinate [label=above:$A$] (A) at (90:3);
    \coordinate [label=below left:$B$] (B) at (210:3);
    \coordinate [label=below right:$C$] (C) at (330:3);

    % Vẽ tam giác ABC
    \draw[thick] (A) -- (B) -- (C) -- cycle;
    \coordinate [label=below:$H$] (H) at ($(B)!0.5!(C)$);

        % Vẽ đường cao AH
        \draw[ thick] (A) -- (H);
            \draw[ thick] (B) -- (O);
                \draw[ thick] (C) -- (O);
\end{tikzpicture}
}
\loigiai{
Ta có $HB= \dfrac{BC}{2} = \dfrac{9}{2}$ nên $AH= \sqrt{ 9^{2} + \dfrac{9}{2}^{2}}= \dfrac{9 \sqrt{3}}{2}$\\
$R=AO= \dfrac{2}{3} \cdot AH =3 \sqrt{3}$
}\end{ex}

